//! Generated certificates for TLS test clusters.
//!
//! [`TestPki`] is a throwaway CA with a server and a client certificate (ECDSA P-256),
//! valid from 2000 to 2049. It never leaves the process except through files in a
//! temporary directory: see [`TlsCluster`].

use std::fs;
use std::io;
use std::path::{Path, PathBuf};

use rcgen::{
    BasicConstraints, CertificateParams, CertifiedIssuer, DnType, ExtendedKeyUsagePurpose, IsCa,
    KeyPair, KeyUsagePurpose, date_time_ymd,
};
use tempfile::TempDir;

use crate::{Error, Result};

/// Common name of the server certificate generated by [`TestPki`].
pub const SERVER_COMMON_NAME: &str = "fdb-test-server";
/// Common name of the client certificate generated by [`TestPki`].
pub const CLIENT_COMMON_NAME: &str = "fdb-test-client";
/// Organization of every certificate [`TestPki`] issues, so a `verify_peers` rule can match
/// it (`S.O=fdb-native-testkit`).
pub const ORGANIZATION: &str = "fdb-native-testkit";

fn pki_error(e: impl std::fmt::Display) -> Error {
    Error::Pki(e.to_string())
}

/// A certificate and its private key, PEM encoded.
#[derive(Clone, Debug)]
pub struct Identity {
    cert_pem: String,
    key_pem: String,
}

impl Identity {
    /// The certificate, PEM.
    pub fn cert_pem(&self) -> &str {
        &self.cert_pem
    }

    /// The private key, PEM (PKCS#8, unencrypted).
    pub fn key_pem(&self) -> &str {
        &self.key_pem
    }
}

/// A CA with a server and a client certificate it issued.
pub struct TestPki {
    ca: CertifiedIssuer<'static, KeyPair>,
    ca_pem: String,
    server: Identity,
    client: Identity,
}

impl std::fmt::Debug for TestPki {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("TestPki").finish_non_exhaustive()
    }
}

impl TestPki {
    /// A new CA named `fdb-test-ca`, with a server certificate
    /// ([`SERVER_COMMON_NAME`]) and a client certificate ([`CLIENT_COMMON_NAME`]).
    pub fn generate() -> Result<Self> {
        Self::generate_named("fdb-test-ca")
    }

    /// Like [`generate`](Self::generate), with the CA's common name set: a second PKI with a
    /// different name is a CA the first one's certificates do not chain to.
    pub fn generate_named(ca_common_name: &str) -> Result<Self> {
        let mut params = CertificateParams::new(Vec::new()).map_err(pki_error)?;
        params.is_ca = IsCa::Ca(BasicConstraints::Unconstrained);
        params.key_usages = vec![KeyUsagePurpose::KeyCertSign, KeyUsagePurpose::CrlSign];
        params
            .distinguished_name
            .push(DnType::CommonName, ca_common_name);
        params
            .distinguished_name
            .push(DnType::OrganizationName, ORGANIZATION);
        window(&mut params);
        let ca = CertifiedIssuer::self_signed(params, KeyPair::generate().map_err(pki_error)?)
            .map_err(pki_error)?;
        let ca_pem = ca.pem();
        let mut pki = Self {
            ca,
            ca_pem,
            server: Identity {
                cert_pem: String::new(),
                key_pem: String::new(),
            },
            client: Identity {
                cert_pem: String::new(),
                key_pem: String::new(),
            },
        };
        pki.server = pki.issue(SERVER_COMMON_NAME)?;
        pki.client = pki.issue(CLIENT_COMMON_NAME)?;
        Ok(pki)
    }

    /// Issues another certificate from the CA, valid for both server and client
    /// authentication, with this common name (and `O=fdb-native-testkit`).
    pub fn issue(&self, common_name: &str) -> Result<Identity> {
        let mut params = CertificateParams::new(vec![common_name.to_owned()]).map_err(pki_error)?;
        params.extended_key_usages = vec![
            ExtendedKeyUsagePurpose::ServerAuth,
            ExtendedKeyUsagePurpose::ClientAuth,
        ];
        params.key_usages = vec![KeyUsagePurpose::DigitalSignature];
        params
            .distinguished_name
            .push(DnType::CommonName, common_name);
        params
            .distinguished_name
            .push(DnType::OrganizationName, ORGANIZATION);
        window(&mut params);
        let key = KeyPair::generate().map_err(pki_error)?;
        let cert = params.signed_by(&key, &self.ca).map_err(pki_error)?;
        Ok(Identity {
            cert_pem: cert.pem(),
            key_pem: key.serialize_pem(),
        })
    }

    /// The CA certificate, PEM.
    pub fn ca_pem(&self) -> &str {
        &self.ca_pem
    }

    /// The server's certificate and key.
    pub fn server(&self) -> &Identity {
        &self.server
    }

    /// The client certificate and key.
    pub fn client(&self) -> &Identity {
        &self.client
    }
}

/// Valid from 2000 until 2049 (the last year UTCTime covers): the container's clock does not
/// matter, and no test outlives the certificates.
fn window(params: &mut CertificateParams) {
    params.not_before = date_time_ymd(2000, 1, 1);
    params.not_after = date_time_ymd(2049, 12, 31);
}

/// The TLS side of a [`FdbContainer`](crate::FdbContainer): the generated certificates and the
/// directory they live in (mounted read-only into the container).
///
/// Files: `ca.pem`, `server-cert.pem`, `server-key.pem`, `client-cert.pem`,
/// `client-key.pem`. The directory is removed when the container handle is dropped.
#[derive(Debug)]
pub struct TlsCluster {
    pki: TestPki,
    dir: TempDir,
}

impl TlsCluster {
    pub(crate) fn new(pki: TestPki) -> io::Result<Self> {
        let dir = tempfile::Builder::new()
            .prefix("fdb-native-testkit-tls-")
            .tempdir()?;
        let write = |name: &str, contents: &str| fs::write(dir.path().join(name), contents);
        write("ca.pem", pki.ca_pem())?;
        write("server-cert.pem", pki.server().cert_pem())?;
        write("server-key.pem", pki.server().key_pem())?;
        write("client-cert.pem", pki.client().cert_pem())?;
        write("client-key.pem", pki.client().key_pem())?;
        make_world_readable(dir.path())?;
        Ok(Self { pki, dir })
    }

    /// The generated PKI.
    pub fn pki(&self) -> &TestPki {
        &self.pki
    }

    /// The directory holding the files (mounted at [`CONTAINER_TLS_DIR`] in the container).
    pub fn dir(&self) -> &Path {
        self.dir.path()
    }

    /// Path of the CA certificate: what a client trusts, and what the server verifies clients
    /// with.
    pub fn ca_path(&self) -> PathBuf {
        self.dir.path().join("ca.pem")
    }

    /// The CA certificate, PEM.
    pub fn ca_pem(&self) -> &str {
        self.pki.ca_pem()
    }

    /// Path of the client certificate.
    pub fn client_cert_path(&self) -> PathBuf {
        self.dir.path().join("client-cert.pem")
    }

    /// Path of the client private key.
    pub fn client_key_path(&self) -> PathBuf {
        self.dir.path().join("client-key.pem")
    }

    /// The client certificate, PEM.
    pub fn client_cert_pem(&self) -> &str {
        self.pki.client().cert_pem()
    }

    /// The client private key, PEM.
    pub fn client_key_pem(&self) -> &str {
        self.pki.client().key_pem()
    }

    /// Path of the server certificate.
    pub fn server_cert_path(&self) -> PathBuf {
        self.dir.path().join("server-cert.pem")
    }

    /// The server certificate, PEM.
    pub fn server_cert_pem(&self) -> &str {
        self.pki.server().cert_pem()
    }
}

/// Where the certificate directory is mounted inside the container.
pub const CONTAINER_TLS_DIR: &str = "/etc/fdb-tls";

/// The mounted files must be readable by whatever user the server runs as. They are throwaway
/// test keys in a directory only this user can list.
#[cfg(unix)]
fn make_world_readable(dir: &Path) -> io::Result<()> {
    use std::os::unix::fs::PermissionsExt;
    // The directory itself stays 0700 for others on the host: Docker's daemon reads it as
    // root, and a rootless daemon runs as this user. Files are 0644 so a non-root container
    // user could read them if the directory allowed it.
    for entry in fs::read_dir(dir)? {
        fs::set_permissions(entry?.path(), fs::Permissions::from_mode(0o644))?;
    }
    Ok(())
}

#[cfg(not(unix))]
fn make_world_readable(_dir: &Path) -> io::Result<()> {
    Ok(())
}
